+  if (semantic?.status === 'blocked') codes.add(semantic.missing_reason ?? 'semantic_or_display_blocked');
+  if (isDisplayBlocked(row)) codes.add('required_visual_display_blocked');
+  if (String(row?.figure_asset_posture ?? '').includes('rights_blocked')) codes.add('rights_display_blocked');
