+
+function buildPayload({
+  sourceMapRow,
+  figureRow,
+  semantic,
+  reviewRouting,
+  fallbackReasonCodes,
+  inputs,
+  paths,
+}) {
+  const row = figureRow ?? sourceMapRow ?? {};
+  const semanticAssertions = [
+    ...arrayFrom(semantic?.accepted_assertions),
+    ...arrayFrom(semantic?.provisional_assertions),
+    ...arrayFrom(semantic?.review_required_assertions),
+    ...arrayFrom(semantic?.blocked_assertions),
+  ];
+  const fallbackOnly = semantic?.status === 'unavailable';
+
+  return {
+    schema_version: PAYLOAD_SCHEMA_VERSION,
+    payload_id: `question-runtime-payload:artifact-adapter:${row.question_key ?? sourceMapRow?.question_key}`,
+    row_presence: {
+      included: true,
+      removal_reason: null,
+      universe: 'v1_9709_governed_3530',
+    },
+    question_identity: {
+      question_id: row.question_key ?? sourceMapRow?.question_key ?? sourceMapRow?.question_row_id,
+      question_key: row.question_key ?? sourceMapRow?.question_key ?? sourceMapRow?.question_row_id,
+      subject_code: row.subject_code ?? sourceMapRow?.subject_code ?? SUBJECT_CODE,
+      question_ref: row.question_ref ?? sourceMapRow?.question_ref ?? null,
+      storage_key: sourceMapRow?.storage_key ?? null,
+    },
+    paper_session_key: {
+      paper_code: row.paper_code ?? sourceMapRow?.paper_code ?? null,
+      year: row.year ?? sourceMapRow?.year ?? null,
+      session: row.session ?? sourceMapRow?.session ?? null,
+      paper_number: row.paper_number ?? sourceMapRow?.paper_number ?? null,
+      variant: row.variant ?? sourceMapRow?.variant ?? null,
+    },
+    question_label: {
+      label: questionLabel(row),
+      q_number: row.q_number ?? sourceMapRow?.q_number ?? null,
+      question_number_text: questionNumberText(row),
+      question_ref_label: row.question_ref ?? sourceMapRow?.question_ref ?? null,
+    },
+    part_metadata: {
+      available: false,
+      part_ref: null,
+      part_label: null,
+      marks_total: null,
+      unavailable_reason: 'part_metadata_not_available_in_current_runtime_source_map',
+    },
+    source_refs: sourceRefsFor({
+      sourceMapRow,
+      figureRow,
+      semanticRefs: semanticRefsFor(semanticAssertions),
+      paths,
+    }),
+    render_display_refs: renderDisplayRefsFor({ sourceMapRow, figureRow }),
+    question_availability:
+      row.question_availability
+      ?? sourceMapRow?.question_availability
+      ?? 'attemptable',
+    display_posture:
+      row.display_posture
+      ?? sourceMapRow?.display_posture
+      ?? 'fallback_only_metadata_display',
+    visual_posture:
+      row.figure_asset_posture
+      ?? sourceMapRow?.figure_asset_posture
+      ?? 'fallback_not_required',
+    rights_fallback: rightsFallbackFor({
+      sourceMapRow,
+      figureRow,
+      fallbackReasonCodes,
+      fallbackOnly,
+    }),
+    semantic_context: semantic,
+    rag_context: ragContextFor({
+      semantic,
+      inputs,
+      paths,
+      fallbackEnabled: fallbackReasonCodes.length > 0 || fallbackOnly,
+    }),
+    copilot_policy: copilotPolicyFor({
+      semantic,
+      displayBlocked: isDisplayBlocked(row),
+    }),
+    review_routing: reviewRouting,
+  };
+}
+
+function sourceArtifactProvenance(sourceArtifacts) {
+  return sourceArtifacts.map((artifact) => ({
+    role: artifact.role,
+    path: artifact.path,
+    exists: artifact.exists,
+    loaded: artifact.loaded,
+    sha256: artifact.sha256,
+  }));
+}
+
+function buildPayloadCandidates({
+  inputs,
+  paths,
+  sourceArtifacts,
+  candidateQuestionKeys,
+}) {
+  if (!isRecord(inputs.schema) || !isRecord(inputs.boundary) || !isRecord(inputs.runtimeSourceMap)) {
+    return [];
+  }
+  const indexes = indexesFromInputs(inputs);
+  const semanticAvailable = semanticLayersAvailable(inputs);
+
+  return candidateQuestionKeys.map((questionKey) => {
+    const sourceMapRow = indexes.runtimeRowsByQuestion.get(questionKey);
+    const figureRow = indexes.figureRowsByQuestion.get(questionKey);
+    if (!sourceMapRow) {
+      return {
+        question_key: questionKey,
+        candidate_status: 'missing_required_source_row',
+        payload: null,
+        validation: {
+          status: 'fail',
+          errors: ['runtime_source_map_row_missing'],
+        },
+        source_artifact_provenance: sourceArtifactProvenance(sourceArtifacts),
+      };
+    }
+
+    const acceptedAssertions = arrayFrom(indexes.acceptedByQuestion.get(questionKey));
+    const provisionalAssertions = arrayFrom(indexes.provisionalByQuestion.get(questionKey));
+    const reviewRequiredAssertions = arrayFrom(indexes.reviewByQuestion.get(questionKey));
+    const blockedAssertions = arrayFrom(indexes.blockedByQuestion.get(questionKey));
+    const semantic = semanticForQuestion({
+      sourceMapRow,
+      figureRow,
+      acceptedAssertions,
+      provisionalAssertions,
+      reviewRequiredAssertions,
+      blockedAssertions,
+      semanticAvailable,
+    });
+    const row = figureRow ?? sourceMapRow;
+    const reviewRouting = reviewRoutingFor({
+      semantic,
+      row,
+      backlogRows: arrayFrom(indexes.backlogByQuestion.get(questionKey)),
+    });
+    const fallbackReasonCodes = fallbackReasonCodesFor({ semantic, row });
+    const payload = buildPayload({
+      sourceMapRow,
+      figureRow,
+      semantic,
+      reviewRouting,
+      fallbackReasonCodes,
+      inputs,
+      paths,
+    });
+    const validation = validateQuestionRuntimePayload({
+      schema: inputs.schema,
+      payload,
+      boundary: inputs.boundary,
+      fixtureId: questionKey,
+    });
+
+    return {
+      question_key: questionKey,
+      candidate_status: validation.status === 'pass' ? 'schema_valid' : 'schema_invalid',
+      payload,
+      validation,
+      source_artifact_provenance: sourceArtifactProvenance(sourceArtifacts),
+    };
+  });
+}
+
+function runtimeDependencyBoundary(inputs) {
+  return {
+    checked_in_artifacts_only: true,
+    remote_supabase_query_required: false,
+    remote_supabase_mutation_performed:
+      inputs.boundary?.summary?.production_supabase_mutation_count > 0 ||
+      inputs.ragLiteHandoff?.summary?.remote_supabase_mutation_count > 0 ||
+      inputs.ragLiteFinalCloseout?.summary?.remote_supabase_mutation_count > 0,
+    production_rag_reindex_performed:
+      inputs.boundary?.summary?.production_rag_reindex_count > 0 ||
+      inputs.ragLiteHandoff?.summary?.production_rag_reindex_count > 0 ||
+      inputs.ragLiteFinalCloseout?.summary?.production_rag_reindex_count > 0,
+    vector_store_mutation_performed:
+      inputs.boundary?.summary?.vector_store_mutation_count > 0 ||
+      inputs.ragLiteHandoff?.summary?.vector_store_mutation_count > 0 ||
+      inputs.ragLiteFinalCloseout?.summary?.vector_store_mutation_count > 0,
+    remote_disposable_supabase_write_performed: false,
+    runtime_api_integration_performed: false,
+    frontend_ui_integration_performed: false,
+  };
+}
+
+function summarizeCandidates(payloadCandidates, inputs) {
+  const semanticStatuses = payloadCandidates.map((candidate) => (
+    candidate.payload?.semantic_context?.status ?? 'missing_payload'
+  ));
+  const validCount = payloadCandidates.filter((candidate) => candidate.validation?.status === 'pass').length;
+  return {
+    validation_status: validCount === payloadCandidates.length ? 'pass' : 'fail',
+    candidate_count: payloadCandidates.length,
+    valid_candidate_count: validCount,
+    invalid_candidate_count: payloadCandidates.length - validCount,
+    runtime_source_map_rows: Array.isArray(inputs.runtimeSourceMap?.rows)
+      ? inputs.runtimeSourceMap.rows.length
+      : null,
+    figureasset_runtime_gate_rows: Array.isArray(inputs.figureassetRuntimeGate?.rows)
+      ? inputs.figureassetRuntimeGate.rows.length
+      : null,
+    semantic_layers_available: semanticLayersAvailable(inputs),
+    accepted_available_count: semanticStatuses.filter((status) => status === 'accepted_available').length,
+    provisional_only_count: semanticStatuses.filter((status) => status === 'provisional_only').length,
+    unavailable_count: semanticStatuses.filter((status) => status === 'unavailable').length,
+    blocked_count: semanticStatuses.filter((status) => status === 'blocked').length,
+    input_diagnostic_count: arrayFrom(inputs.diagnostics).length,
+  };
+}
+
+function buildCandidatesArtifact({
+  paths,
+  generatedAt,
+  sourceArtifacts,
+  payloadCandidates,
+  candidateQuestionKeys,
+  inputs,
+}) {
+  return {
+    schema_version: CANDIDATES_SCHEMA_VERSION,
+    payload_schema_version: PAYLOAD_SCHEMA_VERSION,
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    depends_on_issues: [...DEPENDS_ON_ISSUES],
+    subject_code: SUBJECT_CODE,
+    objective:
