+      validator: paths.validatorOut,
+      readback: paths.readbackOut,
+    },
+    source_artifacts: sourceArtifacts,
+    candidate_selection: {
+      strategy: 'deterministic_contract_coverage_sample',
+      requested_question_keys: [...candidateQuestionKeys],
+      emitted_question_keys: payloadCandidates.map((candidate) => candidate.question_key),
+      all_3530_production_gate_out_of_scope: true,
+    },
+    runtime_dependency_boundary: runtimeDependencyBoundary(inputs),
+    summary: summarizeCandidates(payloadCandidates, inputs),
+    payload_candidates: payloadCandidates,
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        schema_version: CANDIDATES_SCHEMA_VERSION,
+        candidate_question_keys: payloadCandidates.map((candidate) => candidate.question_key),
+        payloads: payloadCandidates.map((candidate) => candidate.payload),
+        source_artifacts: sourceArtifacts.map((artifact) => ({
+          role: artifact.role,
+          path: artifact.path,
+          sha256: artifact.sha256,
+        })),
+      }),
+    },
+  };
+}
+
+function check(status, id, details = {}) {
+  return { id, status: status ? 'pass' : 'fail', ...details };
+}
+
+export function validateQuestionRuntimePayloadArtifactAdapter({
+  candidates,
+  inputs,
+  sourceArtifacts,
+} = {}) {
+  const errors = [];
+  if (!isRecord(candidates)) errors.push('candidates_required');
+  if (!isRecord(inputs)) errors.push('inputs_required');
+
+  const requiredArtifactsLoaded = REQUIRED_SOURCE_ROLES.every((role) => {
+    const artifact = sourceArtifacts?.find((item) => item.role === role);
+    return artifact?.exists === true && artifact?.loaded === true;
+  });
+  if (!isRecord(inputs?.schema)) errors.push('question_runtime_payload_schema_required');
+  if (!isRecord(inputs?.boundary)) errors.push('v1_data_runtime_boundary_required');
+  if (!isRecord(inputs?.runtimeSourceMap)) errors.push('runtime_source_map_required');
+  if (!isRecord(inputs?.figureassetRuntimeGate)) errors.push('figureasset_runtime_gate_required');
+  if (!isRecord(inputs?.ragLiteHandoff)) errors.push('rag_lite_handoff_required');
+  if (!isRecord(inputs?.ragLiteFinalCloseout)) errors.push('rag_lite_final_closeout_required');
+
+  const runtimeSourceMapRows = Array.isArray(inputs?.runtimeSourceMap?.rows)
+    ? inputs.runtimeSourceMap.rows.length
+    : null;
+  const allRuntimeRowsObservable = runtimeSourceMapRows === EXPECTED_RUNTIME_ROW_COUNT;
+  if (isRecord(inputs?.runtimeSourceMap) && !allRuntimeRowsObservable) {
+    errors.push('runtime_source_map_rows_not_3530');
+  }
+
+  const payloadCandidates = arrayFrom(candidates?.payload_candidates);
+  const allCandidatesValidate = payloadCandidates.length > 0 &&
+    payloadCandidates.every((candidate) => candidate?.validation?.status === 'pass');
+  for (const candidate of payloadCandidates) {
+    for (const error of arrayFrom(candidate?.validation?.errors)) {
+      errors.push(error);
+    }
+  }
+
+  const hashesRecorded = arrayFrom(sourceArtifacts)
+    .filter((artifact) => artifact.required === true || artifact.exists === true)
+    .every((artifact) => /^[a-f0-9]{64}$/u.test(String(artifact.sha256)));
+  if (!hashesRecorded) errors.push('source_artifact_hash_missing');
+
+  const dependencyBoundary = candidates?.runtime_dependency_boundary ?? {};
+  const forbiddenRemoteDependenciesAbsent =
+    dependencyBoundary.checked_in_artifacts_only === true &&
+    dependencyBoundary.remote_supabase_query_required === false &&
+    dependencyBoundary.remote_supabase_mutation_performed === false &&
+    dependencyBoundary.production_rag_reindex_performed === false &&
+    dependencyBoundary.vector_store_mutation_performed === false &&
+    dependencyBoundary.remote_disposable_supabase_write_performed === false;
+  if (!forbiddenRemoteDependenciesAbsent) errors.push('forbidden_remote_dependency_present');
+
+  const semanticAvailable = semanticLayersAvailable(inputs ?? {});
+  const missingSemanticKgDegradesWithoutRowDrop = semanticAvailable
+    ? true
+    : payloadCandidates.length > 0 && payloadCandidates.every((candidate) => (
+      candidate.payload?.row_presence?.included === true &&
+      candidate.payload?.semantic_context?.status === 'unavailable' &&
+      candidate.payload?.rights_fallback?.fallback_reason_codes?.includes('semantic_kg_unavailable')
+    ));
+  if (!missingSemanticKgDegradesWithoutRowDrop) {
+    errors.push('missing_semantic_kg_did_not_degrade_runtime_rows');
+  }
+
+  const noCriticalInputDiagnostics = arrayFrom(inputs?.diagnostics)
+    .filter((diagnostic) => diagnostic?.severity === 'critical')
+    .length === 0;
+  if (!noCriticalInputDiagnostics) errors.push('critical_input_diagnostics_present');
+
+  const deterministicCandidateSelection =
+    JSON.stringify(candidates?.candidate_selection?.emitted_question_keys ?? []) ===
+    JSON.stringify(payloadCandidates.map((candidate) => candidate.question_key));
+
+  const checks = [
+    check(requiredArtifactsLoaded, 'required_source_artifacts_loaded'),
+    check(allRuntimeRowsObservable, 'all_3530_source_map_observed', {
+      runtime_source_map_rows: runtimeSourceMapRows,
+    }),
+    check(hashesRecorded, 'source_artifact_hashes_recorded'),
+    check(allCandidatesValidate, 'candidate_payloads_validate'),
+    check(deterministicCandidateSelection, 'deterministic_candidate_selection'),
+    check(forbiddenRemoteDependenciesAbsent, 'forbidden_remote_dependencies_absent'),
+    check(missingSemanticKgDegradesWithoutRowDrop, 'missing_semantic_kg_degrades_without_row_drop'),
+    check(noCriticalInputDiagnostics, 'no_critical_input_diagnostics'),
+  ];
+

