+  if (semantic?.blocked_assertions?.length > 0) reasonCodes.add('semantic_kg_blocked_quarantined');
+  if (isDisplayBlocked(row)) reasonCodes.add('visual_required_display_blocked');
+  if (String(row?.figure_asset_posture ?? '').includes('rights_blocked')) reasonCodes.add('rights_review_required');
